const dialog=document.querySelector('#architecture');
document.querySelector('#open-diagram').onclick=()=>{dialog.showModal();document.body.classList.add('modal-open')};
document.querySelector('#close-diagram').onclick=()=>dialog.close();dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));
const nodes=[
['sources',25,50,'News publishers','Input sources','News publishers supply the articles ingested by the scheduled processing pipeline.'],
['schedule',245,50,'EventBridge','Every two hours','The documented schedule launches a Fargate processing task every two hours. An advisory lock prevents overlapping runs.'],
['pipeline',245,190,'Fargate pipeline','Ingest · analyse · publish','The pipeline collects news, calls translation and analysis services, and prepares finished article groups for publication.'],
['analysis',25,190,'DeepSeek / DeepL','Translation & analysis','The diagram identifies DeepSeek for translation and analysis, with DeepL as the translation fallback.'],
['database',475,190,'PostgreSQL','Pipeline & app schemas','Working state is stored in the pipeline schema. A full-state publication transaction updates the app schema, which is read by the API.'],
['api',705,190,'Flask on Fargate','API & article pages','Behind an Application Load Balancer, the Flask service handles API requests, shared links and web article pages.'],
['readers',925,190,'Readers','Apps & web','Readers access articles through the API and web service. Cover images are fetched separately through CloudFront.'],
['images',705,50,'S3 / CloudFront','Cover images','Cover images selected from Wikimedia Commons are stored in S3 and delivered through CloudFront at the documented image sizes.'],
['support',475,320,'Supporting services','Email · logs · subscriptions','SES provides sign-up verification email, RevenueCat provides subscription events, and CloudWatch collects task logs. ECR and Secrets Manager support task startup.']
];
const ns='http://www.w3.org/2000/svg',world=document.querySelector('#diagram-world');
function svg(tag,attrs,text){const el=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));if(text)el.textContent=text;return el}
const edges=[[185,85,245,225],[325,120,325,190],[185,225,245,225],[405,225,475,225],[635,225,705,225],[865,225,925,225],[785,120,1000,190],[555,320,555,260]];
edges.forEach(([x1,y1,x2,y2])=>world.append(svg('path',{d:`M${x1},${y1} L${x2},${y2}`,stroke:'#92988c','stroke-width':1,fill:'none'})));
nodes.forEach(([id,x,y,title,subtitle,copy])=>{const g=svg('g',{'data-node':id,tabindex:'0',role:'button','aria-label':title,transform:`translate(${x},${y})`});let w=id==='readers'?135:160;g.append(svg('rect',{width:w,height:70,fill:'#292d29',stroke:'#737b6e',rx:2}));g.append(svg('text',{x:12,y:27,fill:'#eee9db','font-size':15,'font-family':'Georgia'},title));g.append(svg('text',{x:12,y:49,fill:'#b9b9ae','font-size':11,'font-family':'Arial'},subtitle));const select=()=>{document.querySelector('#node-title').textContent=title;document.querySelector('#node-copy').textContent=copy;world.querySelectorAll('rect').forEach(r=>r.setAttribute('fill','#292d29'));g.querySelector('rect').setAttribute('fill','#40483e')};g.addEventListener('click',select);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}});world.append(g)});
let scale=1,tx=0,ty=0,start=null;const viewport=document.querySelector('#diagram-viewport');function update(){world.setAttribute('transform',`translate(${tx},${ty}) scale(${scale})`)}function zoom(f){const next=Math.max(.55,Math.min(3,scale*f));tx=540-(540-tx)*next/scale;ty=200-(200-ty)*next/scale;scale=next;update()}
document.querySelector('#zoom-in').onclick=()=>zoom(1.25);document.querySelector('#zoom-out').onclick=()=>zoom(.8);document.querySelector('#reset-diagram').onclick=()=>{scale=1;tx=ty=0;update()};viewport.addEventListener('pointerdown',e=>{if(e.target.closest('[data-node]'))return;start={x:e.clientX,y:e.clientY,tx,ty};viewport.setPointerCapture(e.pointerId)});viewport.addEventListener('pointermove',e=>{if(!start)return;const factor=1080/viewport.clientWidth;tx=start.tx+(e.clientX-start.x)*factor;ty=start.ty+(e.clientY-start.y)*factor;update()});viewport.addEventListener('pointerup',()=>start=null);viewport.addEventListener('pointercancel',()=>start=null);
